"use client";

import { cn } from "@/lib/utils";
import type { Variants } from "motion/react";
import {
 LazyMotion,
 domMin,
 m,
 useAnimation,
 useReducedMotion,
} from "motion/react";
import {
 forwardRef,
 useCallback,
 useImperativeHandle,
 useRef,
 type HTMLAttributes,
} from "react";
export interface ListPlusIconHandle {
 startAnimation: () => void;
 stopAnimation: () => void;
}

interface ListPlusIconProps extends Omit<
 HTMLAttributes<HTMLDivElement>,
 | "color"
 | "onDrag"
 | "onDragStart"
 | "onDragEnd"
 | "onAnimationStart"
 | "onAnimationEnd"
 | "onAnimationIteration"
> {
 size?: number;
 duration?: number;
 isAnimated?: boolean;
 color?: string;
}

const ListPlusIcon = forwardRef<ListPlusIconHandle, ListPlusIconProps>(
 (
  {
   onMouseEnter,
   onMouseLeave,
   className,
   size = 24,
   duration = 1,
   isAnimated = true,
   color,
   ...props
  },
  ref,
 ) => {
  const controls = useAnimation();
  const reduced = useReducedMotion();
  const isControlled = useRef(false);

  useImperativeHandle(ref, () => {
   isControlled.current = true;
   return {
    startAnimation: () =>
     reduced ? controls.start("normal") : controls.start("animate"),
    stopAnimation: () => controls.start("normal"),
   };
  });

  const handleEnter = useCallback(
   (e?: React.MouseEvent<HTMLDivElement>) => {
    if (!isAnimated || reduced) return;
    if (!isControlled.current) controls.start("animate");
    else onMouseEnter?.(e as any);
   },
   [controls, reduced, isAnimated, onMouseEnter],
  );

  const handleLeave = useCallback(
   (e?: React.MouseEvent<HTMLDivElement>) => {
    if (!isControlled.current) controls.start("normal");
    else onMouseLeave?.(e as any);
   },
   [controls, onMouseLeave],
  );

  const rowVariants: Variants = {
   normal: { scaleX: 1, opacity: 1 },
   animate: (i: number) => ({
    scaleX: [0, 1],
    opacity: [0, 1],
    transition: {
     duration: 0.35 * duration,
     ease: "easeOut",
     delay: i * 0.1 * duration,
    },
   }),
  };

  const signVariants: Variants = {
   normal: { scale: 1, opacity: 1, rotate: 0 },
   animate: {
    scale: [0, 1.2, 1],
    opacity: [0, 1, 1],
    rotate: [-90, 0, 0],
    transition: {
     duration: 0.45 * duration,
     ease: "easeOut",
     times: [0, 0.6, 1],
     delay: 0.25 * duration,
    },
   },
  };

  return (
   <LazyMotion features={domMin} strict>
    <m.div
     className={cn("inline-flex items-center justify-center", className)}
     onMouseEnter={handleEnter}
     onMouseLeave={handleLeave}
     {...props}
     style={{ color, ...props.style }}
    >
     <m.svg
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      animate={controls}
      initial="normal"
     >
      <m.path
       d="M16 5H3"
       variants={rowVariants}
       custom={0}
       style={{ transformBox: "view-box", originX: "3px", originY: "5px" }}
      />
      <m.path
       d="M11 12H3"
       variants={rowVariants}
       custom={1}
       style={{ transformBox: "view-box", originX: "3px", originY: "12px" }}
      />
      <m.path
       d="M16 19H3"
       variants={rowVariants}
       custom={2}
       style={{ transformBox: "view-box", originX: "3px", originY: "19px" }}
      />
      <m.g
       variants={signVariants}
       style={{ transformBox: "view-box", originX: "18px", originY: "12px" }}
      >
       <path d="M18 9v6" />
       <path d="M21 12h-6" />
      </m.g>
     </m.svg>
    </m.div>
   </LazyMotion>
  );
 },
);

ListPlusIcon.displayName = "ListPlusIcon";
export { ListPlusIcon };
